from pt import *
TITLE = "GoTube: Scalable Stochastic Verification of Continuous-Depth Models"
items = [
 H("# " + TITLE, (91, 521), 98, 112),
 T(r"Sophie Gruenbacher $^{1\ast}$, Mathias Lechner $^{2}$, Ramin Hasani $^{3}$, Daniela Rus $^{3}$, Thomas A. Henzinger $^{2}$, Scott A. Smolka $^{4}$, Radu Grosu $^{1}$", (124, 488), 130, 158),
 T(r"Footnote \*: $^{1}$TU Wien, $^{2}$IST Austria, $^{3}$CSAIL MIT, $^{4}$Stony Brook University. Correspondence to: sophie.gruenbacher@tuwien.ac.at Code: https://github.com/DatenVorsprung/GoTube", L, 645, 685.5),
 T("Copyright © 2022, Association for the Advancement of Artificial Intelligence (www.aaai.org). All rights reserved.", L, 686, 704),
 OMIT([10, 214, 38, 556], "Vertical arXiv stamp in the left margin ('arXiv:2107.08467v2 [cs.LG] 2 Dec 2021'); the version is recorded in the conversion notes."),
 H("## Abstract", (154, 192), 219, 228),
 T("We introduce a new stochastic verification algorithm that formally quantifies the behavioral robustness of any time-continuous process formulated as a continuous-depth model. Our algorithm solves a set of global optimization (Go) problems over a given time horizon to construct a tight enclosure (Tube) of the set of all process executions starting from a ball of initial states. We call our algorithm GoTube. Through its construction, GoTube ensures that the bounding tube is conservative up to a desired probability and up to a desired tightness. GoTube is implemented in JAX and optimized to scale to complex continuous-depth neural network models. Compared to advanced reachability analysis tools for time-continuous neural networks, GoTube does not accumulate overapproximation errors between time steps and avoids the infamous wrapping effect inherent in symbolic techniques. We show that GoTube substantially outperforms state-of-the-art verification tools in terms of the size of the initial ball, speed, time-horizon, task completion, and scalability on a large set of experiments. GoTube is stable and sets the state-of-the-art in terms of its ability to scale to time horizons well beyond what has been previously possible.", (64, 282.5), 236, 444),
 H("## Introduction", (140, 206), 461, 472),
 T("The use of deep-learning systems powered by continuous-depth models continues to grow, especially due to the revival of neural ordinary differential equations (Neural ODEs) (Chen et al. 2018). These models parametrize the derivative of the hidden states by a neural network. The resulting system of differential equations can perform strong function approximation and generative modeling. Ensuring their safety and robustness in any of these fronts is a major imperative, particularly in high-stakes decision-making applications such as medicine, automation, and finance.", L, 476, 584.5),
 T("A particularly appealing approach is to construct a tight overapproximation of the set of states reached over time according to the neural network’s dynamics (a bounding tube) and provide deterministic or stochastic guarantees for the conservativeness of the tube’s bounds.", L, 585.5, 639),
 FIG("Figure 1", "figure-1", [344, 210, 534, 399]),
 C(r"Figure 1: Reachtubes of LRT-NG (Gruenbacher et al. 2020) and GoTube for a CT-RNN controlling CartPole-v1 environment. CAPD (Kapela et al. 2020) and Flow\* (Chen, Ábrahám, and Sankaranarayanan 2013) failed.", R, 404, 448),
 T(r"*Conversion note on Figure 1 (not printed text): the figure is a 3-D plot with the axes $x_1$, $x_2$ and Time (s); the legend entries are LRT-NG, GoTube (ours) and Sample traces.*", R, 449, 453),
 T(r"Deterministic verification approaches ensure conservative bounds (Chen, Ábrahám, and Sankaranarayanan 2013; Gowal et al. 2018; Mirman, Gehr, and Vechev 2018; Bunel et al. 2020a; Kapela et al. 2020; Gruenbacher et al. 2020), but often sacrifice speed and accuracy (Ehlers 2017), and thus scalability; see CAPD, Flow\*, and LRT-NG in Fig. 1 and Fig. 3. Stochastic methods, on the other hand, only ensure a weaker notion of conservativeness in the form of confidence intervals (stochastic bounds). This, however, allows them to achieve much more accurate and faster verification algorithms that scale up to much larger dynamical system (Shmarov and Zuliani 2015b; Bortolussi and Sanguinetti 2014; Gruenbacher et al. 2021).", R, 473, 616.5),
 T("It was recently shown theoretically that stochastic verification approaches based on Lagrangian reachability (SLR) could provably guarantee confidence intervals for continuous-depth models (Gruenbacher et al. 2021). The proposed theoretical framework suggests performing both stochastic global optimization and local differential optimization (Zhigljavsky and Zilinskas 2008; Pontryagin 2018), and uses *interval arithmetic* to symbolically bound", R, 617.5, 705),
]
